import type { ExtractedString, IocItem, IocReport, IocType, Severity } from "../types";

/**
 * Indicator-of-compromise extraction.
 *
 * Every indicator is derived from an already-extracted string, so the original byte
 * offset is preserved and the caller can jump straight to it in the hex view. Nothing
 * here contacts the network; classification is entirely lexical.
 */

const IOC_TYPES: IocType[] = ["url", "ipv4", "ipv6", "domain", "email", "registry", "path", "base64", "guid", "wallet", "command", "user-agent"];

const URL_PATTERN = /\b(?:https?|ftps?|ws{1,2}s?|file|smb|ldaps?):\/\/[^\s"'<>()\\|^`{}]{3,2048}/gi;
const IPV4_PATTERN = /\b(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\b(?::\d{1,5})?/g;
const IPV6_PATTERN = /\b(?:[0-9A-Fa-f]{1,4}:){2,7}(?::|[0-9A-Fa-f]{1,4})\b/g;
const EMAIL_PATTERN = /\b[A-Za-z0-9._%+-]{1,64}@(?:[A-Za-z0-9-]{1,63}\.){1,8}[A-Za-z]{2,24}\b/g;
const REGISTRY_PATTERN = /\b(?:HKEY_(?:LOCAL_MACHINE|CURRENT_USER|CLASSES_ROOT|USERS|CURRENT_CONFIG)|HKLM|HKCU|HKCR|HKU)\\[\w\\ .{}()$-]{3,300}/gi;
const WINDOWS_PATH_PATTERN = /\b(?:[A-Za-z]:\\|\\\\[A-Za-z0-9._-]{1,64}\\|%[A-Za-z]{3,24}%\\)[\w\\ .$()@{}-]{2,300}/g;
const POSIX_PATH_PATTERN = /(?:^|[\s"'=;:(])(\/(?:usr|etc|var|opt|tmp|home|root|bin|sbin|lib|proc|dev|Library|Applications|System)\/[\w./@+-]{2,300})/g;
const GUID_PATTERN = /\b[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\b/g;
const BASE64_PATTERN = /\b(?:[A-Za-z0-9+/]{4}){10,}(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?/g;
const BTC_PATTERN = /\b(?:[13][a-km-zA-HJ-NP-Z1-9]{25,34}|bc1[a-z0-9]{25,62})\b/g;
const ETH_PATTERN = /\b0x[a-fA-F0-9]{40}\b/g;
const XMR_PATTERN = /\b4[0-9AB][1-9A-HJ-NP-Za-km-z]{93}\b/g;
const USER_AGENT_PATTERN = /\bMozilla\/[45]\.0 \([^)]{0,200}\)[^\r\n"']{0,200}/g;

const COMMAND_PATTERNS: Array<{ pattern: RegExp; note: string; severity: Severity }> = [
  { pattern: /powershell(?:\.exe)?[^\r\n"']{0,300}?\s-(?:e|en|enc|encod|encoded|encodedcommand)\b[^\r\n"']{0,400}/gi, note: "PowerShell encoded command", severity: "critical" },
  { pattern: /powershell(?:\.exe)?[^\r\n"']{0,200}?-(?:nop|noprofile|w\s+hidden|windowstyle\s+hidden|ep\s+bypass|executionpolicy\s+bypass)[^\r\n"']{0,300}/gi, note: "PowerShell execution-policy or window evasion", severity: "high" },
  { pattern: /cmd(?:\.exe)?\s+\/[ckq]\s[^\r\n"']{2,300}/gi, note: "Command shell invocation", severity: "medium" },
  { pattern: /\b(?:certutil|bitsadmin|mshta|regsvr32|rundll32|wmic|msiexec|installutil|cscript|wscript)\b[^\r\n"']{0,300}/gi, note: "Living-off-the-land binary invocation", severity: "high" },
  { pattern: /\bvssadmin[^\r\n"']{0,120}?delete\s+shadows[^\r\n"']{0,120}/gi, note: "Shadow-copy deletion (ransomware behaviour)", severity: "critical" },
  { pattern: /\bbcdedit[^\r\n"']{0,120}?(?:recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)/gi, note: "Recovery-environment tampering", severity: "critical" },
  { pattern: /\bwbadmin\b[^\r\n"']{0,120}?delete\s+(?:catalog|systemstatebackup)/gi, note: "Backup catalog deletion", severity: "critical" },
  { pattern: /\bschtasks(?:\.exe)?\s+\/create[^\r\n"']{0,300}/gi, note: "Scheduled-task persistence", severity: "high" },
  { pattern: /\b(?:curl|wget)\s+(?:-[A-Za-z]+\s+)*https?:\/\/[^\s"']{4,300}/gi, note: "Command-line download", severity: "medium" },
  { pattern: /\bnet(?:\.exe)?\s+(?:user|localgroup)\s[^\r\n"']{2,200}/gi, note: "Account manipulation", severity: "high" },
  { pattern: /\b(?:chmod\s+\+x|nohup|\/bin\/(?:ba)?sh\s+-c|base64\s+-d\s*\|)[^\r\n"']{0,200}/gi, note: "POSIX shell staging", severity: "medium" }
];

/** Hostnames whose TLD looks real. Keeps the domain bucket from filling with `foo.dll`. */
const PLAUSIBLE_TLD = /\.(?:com|net|org|io|co|ru|cn|de|uk|fr|jp|br|in|info|biz|xyz|top|club|online|site|shop|live|icu|pw|cc|tk|ml|ga|cf|gq|su|to|me|tv|us|eu|ch|nl|it|pl|se|no|fi|dk|es|ca|au|nz|za|kr|tw|hk|sg|ir|tr|ua|kz|by|vn|th|id|ph|my|mx|ar|cl|pe|ve|onion)$/i;
/** Extensions that regularly appear as `name.ext` and are not hostnames. */
const FILE_LIKE = /\.(?:dll|exe|sys|so|dylib|bin|dat|log|tmp|cfg|ini|xml|json|txt|png|jpg|jpeg|gif|bmp|ico|svg|css|js|ts|html|htm|php|asp|aspx|jsp|py|rb|pl|sh|bat|cmd|ps1|vbs|jar|class|dex|db|sqlite|pdb|res|rc|obj|lib|manifest|nls|mui|cat|inf|cpl|ocx|drv|scr|msi|cab|zip|rar|7z|gz|tar|pdf|doc|docx|xls|xlsx|ppt|pptx)$/i;

const PRIVATE_IPV4 = /^(?:10\.|127\.|169\.254\.|192\.168\.|172\.(?:1[6-9]|2\d|3[01])\.|0\.|22[4-9]\.|2[3-5]\d\.)/;
/** Dotted quads that are almost always version numbers rather than addresses. */
const VERSION_LIKE = /^(?:[0-4]\.\d{1,3}\.\d{1,3}\.\d{1,3})$/;

const SUSPICIOUS_TLD = /\.(?:tk|ml|ga|cf|gq|xyz|top|club|icu|pw|su|onion|zip|mov)$/i;

function hostOf(url: string): string {
  const withoutScheme = url.replace(/^[A-Za-z][\w+.-]*:\/\//, "");
  const host = withoutScheme.split(/[/?#\\]/, 1)[0] ?? "";
  return host.replace(/^[^@]*@/, "").replace(/:\d+$/, "").toLowerCase();
}

function urlSeverity(url: string): Severity {
  const host = hostOf(url);
  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) return "high";
  if (SUSPICIOUS_TLD.test(host)) return "high";
  if (/^(?:ftp|smb|ldap)/i.test(url)) return "medium";
  if (/\.(?:exe|dll|ps1|scr|hta|jar|vbs|bat|cmd|msi|zip|7z)(?:$|\?)/i.test(url)) return "high";
  return "low";
}

/** Shannon entropy over the characters of a string; used to reject low-variety Base64 candidates. */
function characterEntropy(value: string): number {
  const counts = new Map<string, number>();
  for (const character of value) counts.set(character, (counts.get(character) ?? 0) + 1);
  let entropy = 0;
  for (const count of counts.values()) {
    const probability = count / value.length;
    entropy -= probability * Math.log2(probability);
  }
  return entropy;
}

interface Collector {
  add(type: IocType, value: string, offset: number, severity: Severity, note?: string): void;
}

function createCollector(maxItems: number): { collector: Collector; items: IocItem[]; truncated: () => boolean } {
  const items: IocItem[] = [];
  const seen = new Set<string>();
  let overflow = false;
  return {
    items,
    truncated: () => overflow,
    collector: {
      add(type, value, offset, severity, note) {
        const trimmed = value.trim().replace(/[\s.,;:!?)\]}'"]+$/, "");
        if (trimmed.length < 3 || trimmed.length > 2048) return;
        const key = `${type}�${trimmed.toLowerCase()}`;
        if (seen.has(key)) return;
        if (items.length >= maxItems) { overflow = true; return; }
        seen.add(key);
        items.push({ type, value: trimmed, offset, severity, ...(note ? { note } : {}) });
      }
    }
  };
}

function scan(pattern: RegExp, text: string, handler: (match: RegExpExecArray) => void): void {
  pattern.lastIndex = 0;
  let match = pattern.exec(text);
  let guard = 0;
  while (match !== null && guard < 4000) {
    handler(match);
    if (match.index === pattern.lastIndex) pattern.lastIndex += 1;
    match = pattern.exec(text);
    guard += 1;
  }
}

/**
 * Maps a character index inside a decoded string back to an approximate file offset.
 * UTF-16 encodings occupy two bytes per character, so the index is scaled accordingly.
 */
function offsetOf(item: ExtractedString, characterIndex: number): number {
  const scale = item.encoding === "UTF-16LE" || item.encoding === "UTF-16BE" ? 2 : 1;
  return item.offset + Math.min(item.byteLength, characterIndex * scale);
}

export function extractIocs(strings: ExtractedString[], maxItems = 4000): IocReport {
  const { collector, items, truncated } = createCollector(maxItems);
  const domainCandidates = new Map<string, number>();

  for (const item of strings) {
    const text = item.value;
    if (text.length < 4) continue;

    scan(URL_PATTERN, text, (match) => {
      const url = match[0];
      collector.add("url", url, offsetOf(item, match.index), urlSeverity(url), `Host ${hostOf(url) || "unknown"}`);
      const host = hostOf(url);
      if (host && !/^\d/.test(host)) domainCandidates.set(host, offsetOf(item, match.index));
    });

    scan(IPV4_PATTERN, text, (match) => {
      const raw = match[0];
      const address = raw.split(":")[0] ?? raw;
      if (VERSION_LIKE.test(address)) return;
      const isPrivate = PRIVATE_IPV4.test(address);
      collector.add("ipv4", raw, offsetOf(item, match.index), isPrivate ? "info" : "medium", isPrivate ? "Private, loopback, or reserved range" : "Routable address");
    });

    scan(IPV6_PATTERN, text, (match) => {
      collector.add("ipv6", match[0], offsetOf(item, match.index), "medium");
    });

    scan(EMAIL_PATTERN, text, (match) => {
      collector.add("email", match[0], offsetOf(item, match.index), "low");
    });

    scan(REGISTRY_PATTERN, text, (match) => {
      const key = match[0];
      const persistence = /\\(?:Run|RunOnce|RunServices|Winlogon|Image File Execution Options|AppInit_DLLs|Shell Folders|Startup)\b/i.test(key);
      collector.add("registry", key, offsetOf(item, match.index), persistence ? "high" : "low", persistence ? "Known persistence location" : undefined);
    });

    scan(WINDOWS_PATH_PATTERN, text, (match) => {
      const path = match[0];
      const sensitive = /\\(?:Temp|AppData|ProgramData|Startup|Tasks|System32|SysWOW64|Windows\\Temp)\\/i.test(path);
      collector.add("path", path, offsetOf(item, match.index), sensitive ? "medium" : "info", sensitive ? "Commonly abused directory" : undefined);
    });

    scan(POSIX_PATH_PATTERN, text, (match) => {
      const path = match[1];
      if (!path) return;
      const sensitive = /^\/(?:tmp|dev\/shm|var\/tmp)\//.test(path) || /\/(?:cron|systemd|rc\.local|passwd|shadow|authorized_keys)\b/.test(path);
      collector.add("path", path, offsetOf(item, match.index), sensitive ? "medium" : "info", sensitive ? "Commonly abused location" : undefined);
    });

    scan(GUID_PATTERN, text, (match) => {
      collector.add("guid", match[0], offsetOf(item, match.index), "info");
    });

    scan(USER_AGENT_PATTERN, text, (match) => {
      collector.add("user-agent", match[0], offsetOf(item, match.index), "low", "Hard-coded HTTP User-Agent");
    });

    scan(BTC_PATTERN, text, (match) => {
      collector.add("wallet", match[0], offsetOf(item, match.index), "high", "Bitcoin-style address");
    });
    scan(ETH_PATTERN, text, (match) => {
      collector.add("wallet", match[0], offsetOf(item, match.index), "high", "Ethereum-style address");
    });
    scan(XMR_PATTERN, text, (match) => {
      collector.add("wallet", match[0], offsetOf(item, match.index), "critical", "Monero-style address");
    });

    scan(BASE64_PATTERN, text, (match) => {
      const blob = match[0];
      if (blob.length < 40 || blob.length > 100_000) return;
      // Reject padded hex, GUID fragments, and other low-variety runs that match the charset by accident.
      if (characterEntropy(blob.slice(0, 512)) < 4.2) return;
      if (/^[0-9A-Fa-f]+$/.test(blob)) return;
      const severity: Severity = blob.length >= 512 ? "medium" : "low";
      collector.add("base64", blob.length > 220 ? `${blob.slice(0, 200)}… (${blob.length} chars)` : blob, offsetOf(item, match.index), severity, `${blob.length}-character Base64-like blob`);
    });

    for (const { pattern, note, severity } of COMMAND_PATTERNS) {
      scan(pattern, text, (match) => {
        collector.add("command", match[0], offsetOf(item, match.index), severity, note);
      });
    }

    // Bare hostnames that appear without a scheme.
    scan(/\b(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.){1,6}[A-Za-z]{2,24}\b/g, text, (match) => {
      const host = match[0].toLowerCase();
      if (FILE_LIKE.test(host) || !PLAUSIBLE_TLD.test(host)) return;
      if (!domainCandidates.has(host)) domainCandidates.set(host, offsetOf(item, match.index));
    });
  }

  for (const [host, offset] of domainCandidates) {
    collector.add("domain", host, offset, SUSPICIOUS_TLD.test(host) ? "high" : "low", SUSPICIOUS_TLD.test(host) ? "Top-level domain frequently used for abuse" : undefined);
  }

  const counts = Object.fromEntries(IOC_TYPES.map((type) => [type, 0])) as Record<IocType, number>;
  for (const item of items) counts[item.type] += 1;

  const severityRank: Record<Severity, number> = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };
  items.sort((left, right) => severityRank[left.severity] - severityRank[right.severity] || left.offset - right.offset);

  return { items, counts, truncated: truncated() };
}
